import{_ as a,o as n,c as e,a as s}from"./app.83c7065c.js";const g=JSON.parse('{"title":"nginx配置的一个小错误","description":"","frontmatter":{"title":"nginx配置的一个小错误","date":"2019-10-11"},"headers":[],"relativePath":"2019/nginx-config-mistake.md","lastUpdated":1786184870000}'),p={name:"2019/nginx-config-mistake.md"},o=s(`<h3 id="写在前面" tabindex="-1">写在前面 <a class="header-anchor" href="#写在前面" aria-hidden="true">#</a></h3><p>最近一次帮同事找错误的经历，虽然最后发现是很低级的错误，但是过程挺有意思</p><h3 id="问题描述" tabindex="-1">问题描述 <a class="header-anchor" href="#问题描述" aria-hidden="true">#</a></h3><p>之前搭建的新管理后台项目A上线了，搭档想在本地调试，于是按照文档配好了nginx配置文件，本地启动项目，按域名访问却被重定向到了另一个项目B的页面</p><h3 id="排查过程" tabindex="-1">排查过程 <a class="header-anchor" href="#排查过程" aria-hidden="true">#</a></h3><ol><li><p>检查项目A的ip地址是否正确</p><p>确认是本机ip，没有错，刷新页面，问题依旧</p></li><li><p><code>switchHosts</code>关闭其他项目的host配置，只保留项目A的配置</p><p>清理dns缓存，刷新页面，问题依旧，怀疑<code>nginx</code>配置没有生效</p></li><li><p><code>nginx -t</code> 检查配置</p><p>检查失败，报错<code>“duplicate upstream a-proxy”</code>，定位到A的<code>nginx</code>配置文件</p><p><code>a-proxy</code>是配置的反向代理，在配置文件里大概是这样的</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">server {</span></span>
<span class="line"><span style="color:#A6ACCD;">     ...</span></span>
<span class="line"><span style="color:#A6ACCD;">     location / {</span></span>
<span class="line"><span style="color:#A6ACCD;">         ...</span></span>
<span class="line"><span style="color:#A6ACCD;">         proxy_pass http://a-proxy;</span></span>
<span class="line"><span style="color:#A6ACCD;">     }</span></span>
<span class="line"><span style="color:#A6ACCD;">}</span></span>
<span class="line"><span style="color:#A6ACCD;">upstream a-proxy {</span></span>
<span class="line"><span style="color:#A6ACCD;">    server 127.0.0.1: 12076;</span></span>
<span class="line"><span style="color:#A6ACCD;">}</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre></div><p>google了一下这个错误，说是出现了这个错误说明<code>a-proxy</code>出现了多次，删除多余的就可以，于是排查配置文件</p></li><li><p>A的nginx配置文件中搜索重复的<code>a-proxy</code></p><p>没有找到</p></li><li><p>排查其他<code>server</code>的<code>nginx</code>配置文件，搜索重复的<code>a-proxy</code></p><p>没有找到</p></li><li><p>排查合并的主<code>nginx</code>配置文件，搜索重复的<code>a-proxy</code></p><p>还是没有找到</p></li><li><p>给<code>a-proxy</code>改名，看是否还是报错</p><p>仍然报相同的错误，“duplicate upstream xxx-proxy”，这样基本上可以确认是A的同一份配置文件被加载了多次导致的错误</p></li><li><p>回到主nginx配置文件，开始查找加载的配置代码</p><p>经过排查发现 <code>include servers/*</code>代码出现了多次，正是这个代码导致了同一份配置文件被多次加载。 于是删除多余代码，重新<code>nginx -t</code>检查通过，重启nginx后项目访问正常</p></li></ol><p><strong>总耗时： 1小时</strong></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-hidden="true">#</a></h3><p>经过搭档回忆，起因是之前重装nginx复制粘贴配置文件的时候不小心复制重复了一些内容。</p><p>其他配置尽管重复加载，但没有遇到这个不允许重复的情况，这个问题一直没有暴露出来，直到这次...</p><p>自己对nginx不太熟悉，以后还要抽时间补一补相关知识，以上。</p>`,11),c=[o];function i(l,t,r,d,x,h){return n(),e("div",null,c)}const _=a(p,[["render",i]]);export{g as __pageData,_ as default};
